window.AKT.creatures = [{"id":"werewolf","name":{"ar":"المذءوب","en":"The werewolf"},"kind":"shapeshifter","issues":["mwt-1","mwt-20"],"lore":{"ar":"إنسان يتحول إلى ذئب أو مخلوق نصفه ذئب، غالبًا عند اكتمال البدر، وهو من أقدم أساطير أوروبا.","en":"A person who turns into a wolf or a wolf-like creature, usually under the full moon; one of Europe's oldest legends."},"inBooks":{"ar":"في رومانيا عام 1961 طارد رفعت مذءوبًا تبين أنه خدعة؛ وفي «حكايات التاروت» أقنع لوسيفر سام كولبي بأن أسرة بأكملها مستذئبون.","en":"In Romania in 1961 Refaat hunted a werewolf that proved a hoax; in \"Tarot Tales\" Lucifer convinced Sam Colby that a whole family were werewolves."},"source":"https://en.wikipedia.org/wiki/Werewolf"},{"id":"dracula","name":{"ar":"دراكيولا وفلاد الوالاشي","en":"Dracula / Vlad of Wallachia"},"kind":"vampire","issues":["mwt-1","mwt-34","mwt-35"],"lore":{"ar":"الكونت دراكولا مصاص دماء رواية برام ستوكر (1897)، استُلهم اسمه من فلاد الثالث أمير والاشيا الملقب بالمخوزق.","en":"Count Dracula is the vampire of Bram Stoker's 1897 novel, named after Vlad III, the \"Impaler\" prince of Wallachia."},"inBooks":{"ar":"أول مغامرات رفعت محاولة لإحياء مومياء الكونت دراكيولا عام 1959؛ وفي «الشاحبين» و«دماء دراكيولا» منع فلاد الوالاشي من العودة عبر بوابة هالماجيو.","en":"Refaat's first adventure is an attempt to revive Count Dracula's mummy in 1959; in \"The Pale Ones\" and \"Dracula's Blood\" he stops Vlad of Wallachia returning through the Halmageu gate."},"source":"https://en.wikipedia.org/wiki/Count_Dracula"},{"id":"lilith","name":{"ar":"ليليث","en":"Lilith"},"kind":"vampire","issues":[],"lore":{"ar":"شيطانة في التراث اليهودي، تقول الحكايات إنها زوجة آدم الأولى، وتُصوَّر خاطفة للأطفال ومغوية للرجال.","en":"A female demon of Jewish folklore, said in some tales to be Adam's first wife, pictured as a stealer of babies and seducer of men."},"inBooks":{"ar":"في «أسطورة مصاص الدماء»، إحدى مغامرات رفعت الثلاث المنشورة على موقع «روايتي» خارج السلسلة، يحكي عن مواجهته مصاصة الدماء ليليث.","en":"In \"The Legend of the Vampire\", one of three Refaat stories published outside the series on the Riwayti website, he tells of facing the vampire Lilith."},"source":"https://en.wikipedia.org/wiki/Lilith"},{"id":"naddaha","name":{"ar":"النداهة","en":"The Naddaha"},"kind":"folk","issues":["mwt-2"],"lore":{"ar":"من الفولكلور الريفي المصري: روح أنثوية حسناء تنادي الرجال بأسمائهم ليلًا فتجذبهم إلى النيل والترع، ومن يلحق بها يهلك أو يختفي.","en":"From Egyptian rural folklore: a beautiful female spirit who calls men by name at night and lures them to the Nile and the canals; whoever follows her dies or vanishes."},"inBooks":{"ar":"في كفر بدر لبّى رضا أخو رفعت نداء النداهة ثم نادت رفعت نفسه، قبل أن يكشف تحليل الدم أن وراءها خدعة بشرية.","en":"In Kafr Badr Refaat's brother Reda answered the Naddaha's call, then she called Refaat himself, until a blood test revealed a human hoax behind it."},"source":"https://en.wikipedia.org/wiki/El_Naddaha"},{"id":"loch-ness","name":{"ar":"وحش بحيرة لوخ نس","en":"The Loch Ness Monster"},"kind":"creature","issues":["mwt-3"],"lore":{"ar":"مخلوق يُقال إنه يسكن بحيرة لوخ نس في المرتفعات الإسكتلندية، اشتهر بصورة «الجرّاح» عام 1934 التي ثبت تزويرها.","en":"A creature said to live in Loch Ness in the Scottish Highlands, made famous by the 1934 \"surgeon's photograph\", later shown to be a fake."},"inBooks":{"ar":"يحمل السير ماكيلوب الوحش على الظهور فيظهر فعلًا، وينقذ رفعت ماجي منه قبل أن يأخذها قربانًا.","en":"Sir McKillop lures the monster into showing itself and it does; Refaat saves Maggie before it takes her as an offering."},"source":"https://en.wikipedia.org/wiki/Loch_Ness_Monster"},{"id":"cannibal","name":{"ar":"آكل لحوم البشر","en":"The cannibal"},"kind":"other","issues":["mwt-4"],"lore":{"ar":"أكل البشر لحوم بني جنسهم، عُرف تاريخيًا في طقوس بعض الشعوب وفي المجاعات، وصار من أعمدة أدب الرعب.","en":"Humans eating human flesh, known historically in some peoples' rituals and in famines, and a staple of horror fiction."},"inBooks":{"ar":"يظن رفعت جاره المثّال عزت آكل بشر، ويظن د. شاهين رفعت آكل بشر؛ والحقيقة سوء تفاهم مضحك.","en":"Refaat suspects his neighbour Ezzat, a sculptor, of cannibalism, and Dr. Shaheen suspects Refaat; it is all a comic misunderstanding."},"source":"https://en.wikipedia.org/wiki/Human_cannibalism"},{"id":"ghoul","name":{"ar":"الغول","en":"The ghoul"},"kind":"folk","issues":["mwt-69"],"lore":{"ar":"الغول في التراث العربي كائن يسكن الخرائب والمقابر ويأكل لحوم البشر والموتى، وقد يتشكل في صور مختلفة.","en":"In Arabic folklore the ghoul haunts ruins and graveyards and feeds on human flesh and the dead, often taking other shapes."},"inBooks":{"ar":"صديقه د. سامي فهيم يتحول إلى غول آدمي في «نادي الغيلان»، ويواجه رفعت مع عادل جماعة تريد إحياء الغول الكامن في البشر.","en":"His friend Dr. Sami Fahim becomes a human ghoul in \"The Ghouls' Club\"; Refaat and Adel face a group out to awaken the ghoul that civilisation buried in humans."},"source":"https://en.wikipedia.org/wiki/Ghoul"},{"id":"zombie","name":{"ar":"الزومبي","en":"The zombie"},"kind":"undead","issues":["mwt-5"],"lore":{"ar":"في الفودو الهايتي، الزومبي جثة يعيدها ساحر إلى الحياة ويسخّرها عبدًا بلا إرادة.","en":"In Haitian Vodou a zombie is a corpse raised by a sorcerer and kept as a will-less slave."},"inBooks":{"ar":"في جمايكا يتضح أن «الموتى الأحياء» غطاء لطبيب فرنسي يستغل مرضى الجذام عمالة مجانية.","en":"In Jamaica the \"living dead\" turn out to be a cover for a French doctor exploiting leprosy patients as free labour."},"source":"https://en.wikipedia.org/wiki/Zombie"},{"id":"medusa","name":{"ar":"رأس ميدوسا","en":"Medusa's head"},"kind":"myth","issues":["mwt-6"],"lore":{"ar":"في الأساطير الإغريقية، ميدوسا جورجونة شعرها أفاعٍ وتحيل من ينظر إليها حجرًا، قطع رأسها البطل برسيوس.","en":"In Greek myth Medusa is a Gorgon with snakes for hair whose gaze turns onlookers to stone; the hero Perseus cut off her head."},"inBooks":{"ar":"زميلة دراسته تابيثا ماكجفرت وزوجها اليوناني يحاولان إقناعه بأن رأس ميدوسا موجود، فيكشف الخدعة.","en":"His former classmate Tabitha McGivert and her Greek husband try to convince him that Medusa's head exists; he sees through the trick."},"source":"https://en.wikipedia.org/wiki/Medusa"},{"id":"pharaohs-curse","name":{"ar":"لعنة الفراعنة","en":"The Pharaoh's curse"},"kind":"other","issues":["mwt-9"],"lore":{"ar":"اعتقاد شاع بعد فتح مقبرة توت عنخ آمون عام 1922 بأن من يزعج المومياوات المصرية تصيبه لعنة قاتلة.","en":"A belief that spread after Tutankhamun's tomb was opened in 1922: whoever disturbs an Egyptian mummy is struck by a deadly curse."},"inBooks":{"ar":"يحاول رفعت تشريح مومياء الفرعون «أخيروم»، فيطارد حارس الفرعون خطيبته هويدا.","en":"Refaat tries to dissect the mummy of the pharaoh \"Akhirom\", and the pharaoh's guardian hunts his fiancée Huwaida."},"source":"https://en.wikipedia.org/wiki/Curse_of_the_pharaohs"},{"id":"mummy","name":{"ar":"المومياء","en":"The mummy"},"kind":"undead","issues":["mwt-1","mwt-9","mwt-48"],"lore":{"ar":"الجثث المحنطة التي صارت في أفلام الرعب منذ ثلاثينيات القرن العشرين وحوشًا تعود إلى الحياة.","en":"Embalmed bodies that horror films since the 1930s have turned into monsters that rise again."},"inBooks":{"ar":"من مومياء دراكيولا في العدد الأول إلى «أسطورة المومياء» التي يقول فيها رفعت إن «ليست كل المومياوات لطيفة المعشر».","en":"From Dracula's mummy in the first issue to \"The Legend of the Mummy\", where Refaat warns that \"not all mummies are good company\"."},"source":"https://en.wikipedia.org/wiki/Mummy_(undead)"},{"id":"spontaneous-combustion","name":{"ar":"الاحتراق التلقائي","en":"Spontaneous human combustion"},"kind":"other","issues":["mwt-13"],"lore":{"ar":"ظاهرة مزعومة لاحتراق جسد إنسان دون مصدر نار خارجي ظاهر، يتداولها الناس منذ القرن الثامن عشر.","en":"A claimed phenomenon of a human body burning with no apparent outside source of fire, told since the 18th century."},"inBooks":{"ar":"أناس يحترقون في ثوانٍ فلا يبقى منهم سوى رماد وألسنة من اللهب الأزرق، ورفعت يفتش عن السر.","en":"People burst into flame in seconds, leaving only ash and tongues of blue fire, and Refaat searches for the secret."},"source":"https://en.wikipedia.org/wiki/Spontaneous_human_combustion"},{"id":"yeti","name":{"ar":"رجل الثلوج (الياتي)","en":"The Yeti"},"kind":"creature","issues":["mwt-14"],"lore":{"ar":"مخلوق ضخم يشبه القرد يُقال إنه يعيش في جبال الهيمالايا، ويسمى «رجل الثلوج البغيض».","en":"A large ape-like creature said to live in the Himalayas, also called the Abominable Snowman."},"inBooks":{"ar":"يسمونه «مي جي» بالمنغولية و«ياتي» في التبت، ويواجه رفعت لغز آثار قدميه على الثلج.","en":"Called \"Mi-gyi\" in Mongolian and \"Yeti\" in Tibet; Refaat faces the riddle of its footprints in the snow."},"source":"https://en.wikipedia.org/wiki/Yeti"},{"id":"man-eating-plant","name":{"ar":"النبات القاتل","en":"The killer plant"},"kind":"creature","issues":["mwt-15"],"lore":{"ar":"حكايات «الشجرة آكلة البشر» انتشرت منذ القرن التاسع عشر، أشهرها خدعة شجرة مدغشقر عام 1874.","en":"Tales of the \"man-eating tree\" spread from the 19th century, the best known being the 1874 Madagascar tree hoax."},"inBooks":{"ar":"نبات «الموكاسا نيجرا» يفكر ويتحرك ويقتل، ويطارد رفعت حتى قريته، وفي أثناء ذلك تموت أمه.","en":"The Mukasa Nigra plant thinks, moves and kills; it hunts Refaat as far as his village, and his mother dies meanwhile."},"source":"https://en.wikipedia.org/wiki/Man-eating_tree"},{"id":"minotaur","name":{"ar":"المينوتور","en":"The Minotaur"},"kind":"myth","issues":["mwt-22"],"lore":{"ar":"في الأساطير الإغريقية، مخلوق برأس ثور وجسد إنسان حُبس في متاهة كريت وقتله ثيسيوس.","en":"In Greek myth a creature with a bull's head and a man's body, kept in the Labyrinth of Crete and slain by Theseus."},"inBooks":{"ar":"تصل رفعت رسالة من تابيثا ماكجفرت في اليونان عن المينوتور، وعظام مبعثرة وخطوات في الظلام.","en":"A letter reaches Refaat from Tabitha McGivert in Greece about the Minotaur: scattered bones and footsteps in the dark."},"source":"https://en.wikipedia.org/wiki/Minotaur"},{"id":"esp","name":{"ar":"الإدراك فوق الحسي","en":"Extrasensory perception"},"kind":"other","issues":["mwt-24","mwt-25","mwt-26","mwt-39"],"lore":{"ar":"قدرة مزعومة على تلقي المعلومات بغير الحواس الخمس، كالتخاطر والاستبصار، درسها جوزيف راين في ثلاثينيات القرن العشرين.","en":"A claimed ability to receive information beyond the five senses, such as telepathy and clairvoyance, studied by J. B. Rhine in the 1930s."},"inBooks":{"ar":"البولندي إيجور تاركوفسكي يرسل لرفعت خطابًا طويلًا عن قصته مع الإدراك فوق الحسي يقدمه في ثلاثة كتيبات، ثم يستعين به رفعت في «أسطورة التوءمين».","en":"The Pole Igor Tarkovsky sends Refaat a long letter about his life with ESP, presented over three issues; later Refaat calls on him in \"The Legend of the Twins\"."},"source":"https://en.wikipedia.org/wiki/Extrasensory_perception"},{"id":"jathoom","name":{"ar":"الجاثوم","en":"The Jathoom (sleep paralysis)"},"kind":"demon","issues":["mwt-29"],"lore":{"ar":"في الموروث العربي كائن يجثم على صدر النائم فيشلّه؛ والطب يسمي الحالة «شلل النوم» مع هلاوس مفزعة.","en":"In Arab tradition a being that squats on a sleeper's chest and pins him down; medicine calls it sleep paralysis, with frightening hallucinations."},"inBooks":{"ar":"قصة عن الكوابيس، والبقاء وحيدًا في قصر فسيح مظلم يجول فيه كيان مريع.","en":"A story of nightmares and of being alone in a vast dark palace roamed by a dreadful presence."},"source":"https://en.wikipedia.org/wiki/Sleep_paralysis"},{"id":"doppelganger","name":{"ar":"القرين","en":"The doppelgänger"},"kind":"other","issues":["mwt-32"],"lore":{"ar":"في الفولكلور الأوروبي، القرين نسخة مطابقة من الإنسان، ورؤيتها نذير شؤم.","en":"In European folklore the doppelgänger is a living double of a person, and seeing it is an ill omen."},"inBooks":{"ar":"رفعت إسماعيل آخر من عالم موازٍ يأتي ليحتل مكانه، فيعيده رفعت إلى عالمه بالحيلة.","en":"Another Refaat Ismail from a parallel world comes to take his place, and Refaat tricks him back home."},"source":"https://en.wikipedia.org/wiki/Doppelgänger"},{"id":"voodoo-doll","name":{"ar":"دمية الفودو","en":"The voodoo doll"},"kind":"folk","issues":["mwt-37"],"lore":{"ar":"دمى يُعتقد أن ما يصيبها يصيب الشخص الذي تمثله، وتُنسب شعبيًا إلى الفودو في الكاريبي.","en":"Dolls believed to pass whatever is done to them on to the person they represent, popularly linked to Caribbean Vodou."},"inBooks":{"ar":"ساحرتا الفودو الأم مارشا وماريانا بوجادو تستوليان على الدمية التي تمثل زوجة هاري شيلدون طمعًا في الشباب.","en":"The voodoo witches Mother Marsha and Mariana Bogado seize the doll representing Harry Sheldon's wife, seeking youth."},"source":"https://en.wikipedia.org/wiki/Voodoo_doll"},{"id":"frankenstein","name":{"ar":"مسخ فرانكنشتاين","en":"Frankenstein's monster"},"kind":"creature","issues":["mwt-41"],"lore":{"ar":"مخلوق رواية ماري شيلي (1818): جسد يجمعه العالم فيكتور فرانكنشتاين من أشلاء ويبعث فيه الحياة.","en":"The creature of Mary Shelley's 1818 novel: a body pieced together by the scientist Victor Frankenstein and brought to life."},"inBooks":{"ar":"الصواعق تسري في جهاز فيكتور فرانكنشتاين فيُسمع الأنين من تحت الملاءة، ويذهب رفعت إلى ألمانيا ليتحقق من أمر عالِم.","en":"Lightning runs through Victor Frankenstein's apparatus and a groan rises under the sheet; Refaat travels to Germany to look into a scientist."},"source":"https://en.wikipedia.org/wiki/Frankenstein's_monster"},{"id":"peking-man","name":{"ar":"رجل بكين","en":"Peking Man"},"kind":"other","issues":["mwt-44"],"lore":{"ar":"حفريات بشر منقرضين اكتُشفت قرب بكين في عشرينيات القرن العشرين، وضاعت صناديقها عام 1941 ولم يُعثر عليها حتى اليوم.","en":"Fossils of an extinct human found near Beijing in the 1920s; their crates went missing in 1941 and have never been found."},"inBooks":{"ar":"فتح «جوياما» الصناديق فجُنّ ذعرًا وأغمد سيفًا في بطنه، والسؤال لرفعت: ماذا رأى؟","en":"Goyama opened the crates, went mad with terror and drove a sword into his belly; the question for Refaat: what did he see?"},"source":"https://en.wikipedia.org/wiki/Peking_Man"},{"id":"side-of-the-stars","name":{"ar":"جانب النجوم","en":"The Side of the Stars"},"kind":"other","issues":["mwt-35","mwt-46","mwt-50"],"lore":{"ar":"يقول أحمد خالد توفيق إنه أسطورة رومانية: المكان الذي تسكنه كل المسوخ، وله ثغرات تعبر منها إلى عالمنا.","en":"Ahmed Khaled Tawfik says it is a Romanian legend: the place where all monsters live, with gaps through which they cross into our world."},"inBooks":{"ar":"يُخدع رفعت إلى جانب النجوم ليحضر محكمة سادته الذين يطالبون الخطاة برواية آثامهم، فيطلق لوسيفر سراحه.","en":"Refaat is tricked onto the Side of the Stars to attend its masters' court, where sinners must tell their sins, and Lucifer sets him free."},"source":"https://ar.wikipedia.org/wiki/ما_وراء_الطبيعة_(سلسلة)"},{"id":"number-13","name":{"ar":"الرقم 13","en":"The number 13"},"kind":"other","issues":["mwt-51"],"lore":{"ar":"التشاؤم من الرقم 13 (التريسكايديكافوبيا) منتشر في الغرب، حتى إن مبانيَ كثيرة بلا طابق ثالث عشر.","en":"Fear of the number 13 (triskaidekaphobia) is widespread in the West; many buildings skip a 13th floor."},"inBooks":{"ar":"رقم مشئوم وحوادث غامضة وشخص غريب الأطوار يعشق الرقم 13 والقطط السوداء، ومعه طبيب أمراض دم حائر.","en":"An ill-omened number, mysterious deaths and an eccentric who loves the number 13 and black cats, plus a puzzled haematologist."},"source":"https://en.wikipedia.org/wiki/13_(number)"},{"id":"nostradamus","name":{"ar":"نبوءة العرّاف","en":"The seer's prophecy"},"kind":"other","issues":["mwt-54"],"lore":{"ar":"تنبأ نوستراداموس، كما يُقال، بموت الملك هنري الثاني في مبارزة: «الأسد الصغير سيهزم الأسد الكبير» وتُفقأ عينه في قفص ذهبي.","en":"Nostradamus is said to have foretold Henry II's death in a joust: \"the young lion will overcome the old\", his eye pierced in a golden cage."},"inBooks":{"ar":"عرّاف يتلو أمام الملكة هذه النبوءة نفسها في البلاط: الأسد الصغير يهزم الأسد الكبير في مبارزة فردية ويموت ميتة شنيعة.","en":"A seer recites this very prophecy to the queen at court: the young lion beats the old in single combat, who dies a horrible death."},"source":"https://en.wikipedia.org/wiki/Nostradamus"},{"id":"beelzebub","name":{"ar":"ملك الذباب","en":"The Lord of the Flies"},"kind":"demon","issues":["mwt-56"],"lore":{"ar":"بعل زبوب، «سيد الذباب»، إله فلسطيني قديم صار في التراث المسيحي اسمًا لأحد أمراء الشياطين.","en":"Beelzebub, \"lord of the flies\", an ancient Philistine god who became one of the princes of demons in Christian tradition."},"inBooks":{"ar":"جسد مغطى بأسراب الذباب، وجون موهون الذي يصير «ري دي موسكاس»؛ ويهرب رفعت إلى المكسيك من لعنته.","en":"A body hidden under swarms of flies, and John Mohun, who becomes \"Rey de Moscas\"; Refaat flees to Mexico to escape his curse."},"source":"https://en.wikipedia.org/wiki/Beelzebub"},{"id":"witch","name":{"ar":"الساحرة","en":"The witch"},"kind":"folk","issues":["mwt-37","mwt-57","mwt-59"],"lore":{"ar":"الساحرة في الفولكلور الأوروبي امرأة تمارس السحر الأسود وتعقد اجتماعات سرية ليلًا، وقد أُحرقت آلاف النساء بهذه التهمة.","en":"In European folklore the witch practises black magic and gathers in secret at night; thousands of women were burned on the charge."},"inBooks":{"ar":"ساحرة في مقبرة ومعها ماجي، ثم الساحرة رونيل السوداء التي تحتل جسد الطفلة إليانور وتتزوج رفعت بوصفة حب.","en":"A witch in a graveyard with Maggie, then the witch Black Ronel, who takes over the girl Eleanor's body and marries Refaat with a love potion."},"source":"https://en.wikipedia.org/wiki/Witchcraft"},{"id":"pandora","name":{"ar":"صندوق باندورا","en":"Pandora's box"},"kind":"myth","issues":["mwt-62"],"lore":{"ar":"في الأساطير الإغريقية فتحت باندورا الجرة التي أعطاها لها زيوس فانطلقت منها شرور العالم ولم يبقَ فيها إلا الأمل.","en":"In Greek myth Pandora opened the jar Zeus gave her and let out the world's evils, leaving only hope inside."},"inBooks":{"ar":"يرسل لوسيفر الصندوق إلى رفعت على سبيل التسلية، فيهز انفجار بلدة كاملة، ويُتهم القمر المكتمل بالعنف الجنوني الذي أصابها.","en":"Lucifer sends Refaat the box for fun, and an explosion rocks a whole town, with the full moon blamed for its mad violence."},"source":"https://en.wikipedia.org/wiki/Pandora's_box"},{"id":"telekinesis","name":{"ar":"التحريك عن بعد","en":"Telekinesis"},"kind":"other","issues":["mwt-63","mwt-64"],"lore":{"ar":"قدرة مزعومة على تحريك الأشياء بالعقل دون لمسها، لم تثبتها أي تجربة علمية.","en":"A claimed power to move objects with the mind alone, never demonstrated in any scientific test."},"inBooks":{"ar":"رفعت يعرف أصحاب هذه الموهبة، ويرى أن الحقيقيين منهم يخفونها ليندمجوا بين الناس.","en":"Refaat knows people with the gift and believes the real ones hide it to blend in among others."},"source":"https://en.wikipedia.org/wiki/Psychokinesis"},{"id":"shadows","name":{"ar":"قوم الظلال","en":"The shadow people"},"kind":"other","issues":["mwt-71"],"lore":{"ar":"يرى الناس في التراث وفي حكايات الخوارق أشباحًا على هيئة ظلال، ومن لا ظل له في الأساطير مسخ أو ميت.","en":"Folklore and paranormal tales speak of shadow-shaped figures, and in legend whoever casts no shadow is a monster or the dead."},"inBooks":{"ar":"موعظة بسيطة: لا تثق بمن لا ظل له، والأسوأ منه من يتصرف ظله وحده.","en":"A simple moral: never trust anyone without a shadow, and fear even more the one whose shadow acts on its own."},"source":"https://en.wikipedia.org/wiki/Shadow_person"},{"id":"totem","name":{"ar":"الطوطم","en":"The totem"},"kind":"other","issues":["mwt-72"],"lore":{"ar":"الطوطم كائن أو رمز تتخذه قبيلة جدًا روحيًا لها، وأشهره أعمدة الطواطم المنحوتة عند سكان شمال غرب أمريكا الأصليين.","en":"A totem is a being or emblem a clan takes as its spirit ancestor, best known from the carved totem poles of the Pacific Northwest peoples."},"inBooks":{"ar":"شيء يتحرك في المتحف بعد حلول الظلام، ينتزع الأطراف ولا تسجله الكاميرات، فيستنجدون برفعت.","en":"Something moves in the museum after dark, tearing off limbs and invisible to cameras, so they turn to Refaat."},"source":"https://en.wikipedia.org/wiki/Totem"},{"id":"lucifer","name":{"ar":"لوسيفر، حامل الضياء","en":"Lucifer, the Light-Bearer"},"kind":"demon","issues":["mwt-20","mwt-35","mwt-50","mwt-62","mwt-78","mwt-79"],"lore":{"ar":"لوسيفر بالاتينية «حامل الضياء»، اسم كوكب الصبح، صار في التراث المسيحي اسمًا للشيطان قبل سقوطه.","en":"Lucifer, Latin for \"light-bearer\", the name of the morning star, became in Christian tradition a name of Satan before his fall."},"inBooks":{"ar":"د. فرانتز لوسيفر، قارئ التاروت الذي يراه رفعت تجسيدًا للشيطان، يطارده من نيويورك 1968 حتى «حامل الضياء».","en":"Dr. Franz Lucifer, the tarot reader Refaat takes for the devil incarnate, haunts him from New York in 1968 to \"The Light-Bearer\"."},"source":"https://en.wikipedia.org/wiki/Lucifer"},{"id":"tarot","name":{"ar":"أوراق التاروت","en":"Tarot cards"},"kind":"other","issues":["mwt-20"],"lore":{"ar":"أوراق لعب ظهرت في إيطاليا في القرن الخامس عشر، ثم صارت منذ القرن الثامن عشر أداة لقراءة الطالع.","en":"Playing cards from 15th-century Italy that became a fortune-telling tool from the 18th century on."},"inBooks":{"ar":"لوسيفر يقرأ الأوراق لعدد من الغرباء فيزرع في أذهانهم نهايات شنيعة تتحقق.","en":"Lucifer reads the cards for a group of strangers and plants horrible fates in their minds that then come true."},"source":"https://en.wikipedia.org/wiki/Tarot"},{"id":"crowley","name":{"ar":"أليستر كراولي","en":"Aleister Crowley"},"kind":"other","issues":["mwt-78","mwt-79"],"lore":{"ar":"ساحر وكاتب بريطاني (1875–1947) أسس مذهب «ثيليما»، ولقبته الصحافة «أشر رجل في العالم» وسمى نفسه «الوحش 666».","en":"A British occultist and writer (1875–1947) who founded Thelema; the press called him \"the wickedest man in the world\" and he called himself \"the Beast 666\"."},"inBooks":{"ar":"يجلس رفعت مع كراولي الميت منذ سبعين عامًا يتحدثان عن لوسيفر، وتُعيد محاولات كولبي الحمقاء إحياءه.","en":"Refaat sits down with Crowley, dead some seventy years, to talk about Lucifer, after Colby's foolish attempts bring him back."},"source":"https://en.wikipedia.org/wiki/Aleister_Crowley"},{"id":"book-of-thoth","name":{"ar":"كتاب تحوت","en":"The Book of Thoth"},"kind":"myth","issues":["mwt-78","mwt-79"],"lore":{"ar":"في حكايات مصر القديمة كتاب سحري كتبه الإله تحوت بيده، ويمنح قارئه فهم لغة الحيوان وسر الآلهة، كما في قصة ستني خعمواس.","en":"In ancient Egyptian tales a magic book written by the god Thoth himself, granting its reader the speech of animals and the gods' secrets, as in the story of Setne Khamwas."},"inBooks":{"ar":"يفتش لوسيفر في ذكريات أجداد رفعت داخل عقله عن الكتاب الذي خبأه جده الأكبر الحكيم سمعان.","en":"Lucifer searches the memories of Refaat's ancestors inside his mind for the book his forefather, the sage Simeon, hid."},"source":"https://en.wikipedia.org/wiki/Book_of_Thoth"},{"id":"necronomicon","name":{"ar":"كتاب العزيف","en":"Al Azif (the Necronomicon)"},"kind":"other","issues":[],"lore":{"ar":"كتاب سحري مختلق في قصص لافكرافت، نسبه إلى «العربي المجنون» عبد الله الحظرد، واسمه العربي «العزيف».","en":"A fictional grimoire in H. P. Lovecraft's stories, credited to \"the mad Arab\" Abdul Alhazred; its Arabic title is \"Al Azif\"."},"inBooks":{"ar":"تطارد الشياطين رفعت بسبب ما يعرفه عن كتاب العزيف، فيحتاج إلى سام كولبي ليخلّصه منها.","en":"Demons hunt Refaat because of what he knows of the book Al Azif, and he needs Sam Colby to rid him of them."},"source":"https://en.wikipedia.org/wiki/Necronomicon"},{"id":"atlantis","name":{"ar":"أطلنطس","en":"Atlantis"},"kind":"myth","issues":["mwt-80"],"lore":{"ar":"جزيرة ذكرها أفلاطون في محاورتي «طيماوس» و«كريتياس»، قال إنها غرقت في البحر في يوم وليلة.","en":"An island described by Plato in the Timaeus and Critias, which he said sank into the sea in a single day and night."},"inBooks":{"ar":"من الأسئلة المعلقة التي يجيب عنها العدد الأخير: «هل هناك أطلنطس حقًّا؟»","en":"One of the open questions the final issue sets out to answer: \"Is there really an Atlantis?\""},"source":"https://en.wikipedia.org/wiki/Atlantis"},{"id":"borley-rectory","name":{"ar":"بيت بورلي","en":"Borley Rectory"},"kind":"other","issues":["mwt-80"],"lore":{"ar":"بيت قسيس في إسكس بإنجلترا لُقب «أكثر بيوت إنجلترا المسكونة»، واحترق عام 1939.","en":"A rectory in Essex, England, dubbed \"the most haunted house in England\", which burned down in 1939."},"inBooks":{"ar":"«أين بيت بورلي؟» سؤال من أسئلة السلسلة التي حان وقت الإجابة عنها في «أسطورة الأساطير».","en":"\"Where is Borley Rectory?\" is one of the series' questions that \"The Legend of Legends\" finally answers."},"source":"https://en.wikipedia.org/wiki/Borley_Rectory"},{"id":"haunted-house","name":{"ar":"البيت المسكون","en":"The haunted house"},"kind":"other","issues":["mwt-12","mwt-47","mwt-67"],"lore":{"ar":"بيت يُعتقد أن أرواحًا أو قوى خفية تسكنه، من أقدم ثيمات حكايات الأشباح منذ رسائل بليني الأصغر.","en":"A house believed to be inhabited by spirits or unseen forces, one of the oldest ghost-story themes, going back to Pliny the Younger."},"inBooks":{"ar":"بيت في المنصورة صنع لرفعت وأبناء خاله صديقة وهمية اسمها شيراز، وعاد يطاردهم بعد عقود حتى أحرقوه.","en":"A house in Mansoura conjured an imaginary playmate, Shiraz, for Refaat and his cousins, and came after them decades later until they burned it."},"source":"https://en.wikipedia.org/wiki/Haunted_house"},{"id":"ghost","name":{"ar":"الشبح","en":"The ghost"},"kind":"undead","issues":["mwt-10","mwt-60"],"lore":{"ar":"روح الميت حين تظهر للأحياء، وتؤمن بها ثقافات كثيرة منذ القدم.","en":"The spirit of a dead person appearing to the living, believed in by many cultures since antiquity."},"inBooks":{"ar":"شبح شاكر بك يحضر حلقة الرعب الأولى في صورة أحد الحاضرين، وشبح مازن أبو سيف يحكي لرفعت حكايات «المتحف الأسود».","en":"The ghost of Shaker Bey attends the first Horror Circle disguised as a guest, and the ghost of Mazen Abu Seif tells Refaat the tales of \"The Black Museum\"."},"source":"https://en.wikipedia.org/wiki/Ghost"}];
